-- Zachary Zeller (profileID=26) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Zachary Zeller phrasings

SELECT p.argumentID, p.phrasingID, 26, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 26
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 26 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=26 AND targArgID IN (101,103,123,175,221,226,230,237,238,242,244,245,278,279,280,281,282,283,285,313,317,318,319,320,321,322,323,400,405,406,412,414,416,476,477,527,528,530,560,561,598,682,685,692,704,706,757,762,772,773,774,776,780,781,782,783,784,786,787,788,789,806,825,827,839,840,841,842,843,863,892,893);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 26
SET pe.active = o.acceptance
WHERE pe.profileID = 26;

SELECT 'Done: endorsements for profileID=26' AS status;